_ZERO_DIGITS = {"CLP", "ISK", "JPY", "KRW", "UGX", "VND"}
_THREE_DIGITS = {"BHD", "JOD", "KWD", "OMR", "TND"}

# Link names (rejected by the API) and the canonical ids to send instead.
_LINKS = {
    "US/Pacific": "America/Los_Angeles",
    "US/Eastern": "America/New_York",
    "US/Central": "America/Chicago",
    "US/Mountain": "America/Denver",
    "US/Alaska": "America/Anchorage",
    "US/Hawaii": "Pacific/Honolulu",
    "US/Arizona": "America/Phoenix",
    "Asia/Calcutta": "Asia/Kolkata",
    "Asia/Saigon": "Asia/Ho_Chi_Minh",
    "Europe/Kiev": "Europe/Kyiv",
    "America/Buenos_Aires": "America/Argentina/Buenos_Aires",
    "Brazil/East": "America/Sao_Paulo",
    "UTC": "Etc/UTC",
    "GMT": "Etc/UTC",
}

_LOCALES = {"en-US", "en-GB", "en-IN", "de-DE", "de-CH", "fr-FR", "pt-BR", "es", "ja-JP"}

_NBSP = "\u00a0"
# locale -> (decimal separator, group separator, code position)
_STYLES = {
    "en-US": (".", ",", "before"),
    "en-GB": (".", ",", "before"),
    "ja-JP": (".", ",", "before"),
    "en-IN": (".", ",", "before"),
    "pt-BR": (",", ".", "before"),
    "de-DE": (",", ".", "after"),
    "es": (",", ".", "after"),
    "de-CH": (".", "\u2019", "after"),
    "fr-FR": (",", "\u202f", "after"),
}


def _tzdata_links() -> dict[str, str]:
    """Link names of the system tz database, as a fallback to the table above."""
    import zoneinfo

    for root in zoneinfo.TZPATH:
        try:
            with open(f"{root}/tzdata.zi", encoding="ascii") as f:
                links = {}
                for row in f:
                    if row.startswith("L "):
                        _, target, name = row.split()
                        links[name] = target
                return links
        except (OSError, ValueError):
            continue
    return {}


def _zone(tz: str) -> str:
    """The canonical zone id for a stored zone name or fixed offset."""
    tz = tz.strip()
    m = re.fullmatch(r"(?:UTC|GMT)?\s*([+-\u2212])(\d{1,2})(?::?(\d{2}))?", tz)
    if m:
        sign = -1 if m.group(1) in "-\u2212" else 1
        hours, minutes = int(m.group(2)), int(m.group(3) or 0)
        if minutes:
            raise ValueError(f"offset {tz!r} is not a whole number of hours")
        offset = sign * hours
        if offset == 0:
            return "Etc/UTC"
        # POSIX convention: the sign is inverted.
        return f"Etc/GMT{'-' if offset > 0 else '+'}{abs(offset)}"
    if tz in _LINKS:
        return _LINKS[tz]
    if tz.startswith("Etc/"):
        if tz in ("Etc/GMT", "Etc/GMT+0", "Etc/GMT-0", "Etc/GMT0", "Etc/Greenwich", "Etc/UCT", "Etc/Universal", "Etc/Zulu"):
            return "Etc/UTC"
        return tz
    links = _tzdata_links()
    seen = set()
    while tz in links and tz not in seen:
        seen.add(tz)
        tz = links[tz]
    return "Etc/UTC" if tz in ("Etc/GMT", "Etc/UCT") else tz


def _locale(posix: str) -> str:
    """The BCP 47 tag of the supported locale for an account's POSIX locale."""
    name = re.split(r"[.@]", posix.strip(), maxsplit=1)[0]
    parts = re.split(r"[_-]", name)
    lang = parts[0].lower()
    region = parts[1].upper() if len(parts) > 1 and parts[1] else ""
    if region and f"{lang}-{region}" in _LOCALES:
        return f"{lang}-{region}"
    if lang in _LOCALES:
        return lang
    return "en-US"


def _digits(currency: str) -> int:
    if currency in _ZERO_DIGITS:
        return 0
    if currency in _THREE_DIGITS:
        return 3
    return 2


def _amount(value: str, digits: int) -> Decimal:
    q = Decimal(value).quantize(Decimal(1).scaleb(-digits), rounding=ROUND_HALF_EVEN)
    return abs(q) if q == 0 else q


def _group(integer: str, locale: str) -> str:
    if locale == "es" and len(integer) == 4:
        return integer
    if locale == "en-IN" and len(integer) > 3:
        head, tail = integer[:-3], integer[-3:]
        pieces = []
        while len(head) > 2:
            pieces.insert(0, head[-2:])
            head = head[:-2]
        if head:
            pieces.insert(0, head)
        return ",".join(pieces + [tail])
    pieces = []
    while len(integer) > 3:
        pieces.insert(0, integer[-3:])
        integer = integer[:-3]
    pieces.insert(0, integer)
    return "\x00".join(pieces)


def _text(value: Decimal, currency: str, locale: str) -> str:
    dec, grp, pos = _STYLES[locale]
    digits = _digits(currency)
    value = _amount(str(value), digits)
    sign = "-" if value < 0 else ""
    integer, _, frac = f"{abs(value):f}".partition(".")
    number = _group(integer, locale).replace("\x00", grp)
    if digits:
        number += dec + frac
    number = sign + number
    return f"{currency}{_NBSP}{number}" if pos == "before" else f"{number}{_NBSP}{currency}"

